#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    unordered_set<string> pref[11], suff[11];

    for (int k = 0; k < N; ++k) {
        string T;
        cin >> T;

        bool invalid = false;

        for (int r = 0; r <= 10; ++r) {
            if (r > 0 && !suff[r].count(T.substr(0, r))) continue;

            int i = 10 - r;
            if (i > 0 && !pref[i].count(T.substr(r, i))) continue;

            invalid = true;
            break;
        }

        if (invalid) {
            cout << T << '\n';
            return 0;
        }

        for (int len = 1; len <= 10; ++len) {
            pref[len].insert(T.substr(0, len));
            suff[len].insert(T.substr(10 - len, len));
        }
    }

    cout << "ok\n";
    return 0;
}
